// StorageProvisioningServiceServer is the server API for StorageProvisioningService service.
// All implementations must embed UnimplementedStorageProvisioningServiceServer
// for forward compatibility.
type StorageProvisioningServiceServer interface {
	// Physical Devices & Disks
	ListDevices(context.Context, *ListDevicesRequest) (*ListDevicesResponse, error)
	RescanDevices(context.Context, *RescanDevicesRequest) (*RescanDevicesResponse, error)
	InitializeDisk(context.Context, *InitializeDiskRequest) (*InitializeDiskResponse, error)
	WipeDisk(context.Context, *WipeDiskRequest) (*WipeDiskResponse, error)
	GetDiskHealth(context.Context, *GetDiskHealthRequest) (*GetDiskHealthResponse, error)
	// Partitions & Filesystems
	CreatePartition(context.Context, *CreatePartitionRequest) (*CreatePartitionResponse, error)
	DeletePartition(context.Context, *DeletePartitionRequest) (*DeletePartitionResponse, error)
	FormatPartition(context.Context, *FormatPartitionRequest) (*FormatPartitionResponse, error)
	ResizePartition(context.Context, *ResizePartitionRequest) (*ResizePartitionResponse, error)
	MountFilesystem(context.Context, *MountFilesystemRequest) (*MountFilesystemResponse, error)
	UnmountFilesystem(context.Context, *UnmountFilesystemRequest) (*UnmountFilesystemResponse, error)
	// LVM
	ListLvm(context.Context, *ListLvmRequest) (*ListLvmResponse, error)
	CreateLvmPv(context.Context, *CreateLvmPvRequest) (*CreateLvmPvResponse, error)
	RemoveLvmPv(context.Context, *RemoveLvmPvRequest) (*RemoveLvmPvResponse, error)
	CreateLvmVg(context.Context, *CreateLvmVgRequest) (*CreateLvmVgResponse, error)
	RemoveLvmVg(context.Context, *RemoveLvmVgRequest) (*RemoveLvmVgResponse, error)
	CreateLvmLv(context.Context, *CreateLvmLvRequest) (*CreateLvmLvResponse, error)
	RemoveLvmLv(context.Context, *RemoveLvmLvRequest) (*RemoveLvmLvResponse, error)
	CreateLvmThinPool(context.Context, *CreateLvmThinPoolRequest) (*CreateLvmThinPoolResponse, error)
	// ZFS
	ListZfs(context.Context, *ListZfsRequest) (*ListZfsResponse, error)
	CreateZpool(context.Context, *CreateZpoolRequest) (*CreateZpoolResponse, error)
	DestroyZpool(context.Context, *DestroyZpoolRequest) (*DestroyZpoolResponse, error)
	CreateZfsDataset(context.Context, *CreateZfsDatasetRequest) (*CreateZfsDatasetResponse, error)
	DestroyZfsDataset(context.Context, *DestroyZfsDatasetRequest) (*DestroyZfsDatasetResponse, error)
	CreateZfsZvol(context.Context, *CreateZfsZvolRequest) (*CreateZfsZvolResponse, error)
	// Storage Pools (Declarative Ceph RBD, ZFS, LVM, NFS, Dir)
	ListStoragePools(context.Context, *ListStoragePoolsRequest) (*ListStoragePoolsResponse, error)
	GetStoragePool(context.Context, *GetStoragePoolRequest) (*GetStoragePoolResponse, error)
	CreateStoragePool(context.Context, *CreateStoragePoolRequest) (*CreateStoragePoolResponse, error)
	UpdateStoragePool(context.Context, *UpdateStoragePoolRequest) (*UpdateStoragePoolResponse, error)
	DeleteStoragePool(context.Context, *DeleteStoragePoolRequest) (*DeleteStoragePoolResponse, error)
	// Volume Lifecycle on Storage Pools (Ceph RBD, ZFS, LVM, Directory)
	CreateVolume(context.Context, *CreateVolumeRequest) (*CreateVolumeResponse, error)
	DeleteVolume(context.Context, *DeleteVolumeRequest) (*DeleteVolumeResponse, error)
	ResizeVolume(context.Context, *ResizeVolumeRequest) (*ResizeVolumeResponse, error)
	ListVolumes(context.Context, *ListVolumesRequest) (*ListVolumesResponse, error)
	// Inheritable QoS & Live Throttling (QEMU iotune)
	SetDiskQoS(context.Context, *SetDiskQoSRequest) (*SetDiskQoSResponse, error)
	GetDiskQoS(context.Context, *GetDiskQoSRequest) (*GetDiskQoSResponse, error)
	// Software RAID (mdadm)
	ListRaidSets(context.Context, *ListRaidSetsRequest) (*ListRaidSetsResponse, error)
	CreateRaidSet(context.Context, *CreateRaidSetRequest) (*CreateRaidSetResponse, error)
	AssembleRaidSet(context.Context, *AssembleRaidSetRequest) (*AssembleRaidSetResponse, error)
	GrowRaidSet(context.Context, *GrowRaidSetRequest) (*GrowRaidSetResponse, error)
	FailRaidMember(context.Context, *FailRaidMemberRequest) (*FailRaidMemberResponse, error)
	RemoveRaidMember(context.Context, *RemoveRaidMemberRequest) (*RemoveRaidMemberResponse, error)
	ReplaceRaidMember(context.Context, *ReplaceRaidMemberRequest) (*ReplaceRaidMemberResponse, error)
	DeleteRaidSet(context.Context, *DeleteRaidSetRequest) (*DeleteRaidSetResponse, error)
	// Migration Pre-Flight Classifier (Zero-Disk-Copy vs Block Copy)
	CheckMigrationStorage(context.Context, *CheckMigrationStorageRequest) (*CheckMigrationStorageResponse, error)
	mustEmbedUnimplementedStorageProvisioningServiceServer()
}

